def make(i, boom=False):
    async def job():
        try:
            if boom:
                await asyncio.sleep(0.005)
                raise ValueError("boom")
            await asyncio.sleep(10)
        finally:
            cleaned.append(i)
    return job

async def main_():
    try:
        await run_tasks([make(0), make(1, boom=True), make(2)], max_concurrent=5)
    except ValueError:
        return "propagated"
    return "swallowed"

result = asyncio.run(main_())
if result != "propagated":
    fail(f"task exception did not propagate (got {result!r})")
